        res_0 = requests \
                .put(self.baseUrlOfSut + "/api/v1/projects/933/views/864/buckets",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 412
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["code"] == 2002
        assert res_0.json()["message"] == "Invalid Data"
        assert len(res_0.json()["invalid_fields"]) == 1
        assert res_0.json()["invalid_fields"][0] == "title: non zero value required"


